def row(rid, fact_ids, strata, tid, lang, q, keys, req=True):
    return {"id": rid, "task": "facts", "fact_ids": fact_ids, "strata": strata, "template_id": tid,
            "lang": lang, "question": q, "answer_keys": keys, "require_all": req}


